//! Chains blindsight knows by name: those with an official Safe deployment.
//!
//! Data: `data/chains.json`, generated by `scripts/fixtures/gen_chains.py`
//! from `ethereum-lists/chains` (the source behind chainid.network).

use std::collections::BTreeMap;
use std::sync::LazyLock;

use serde::Deserialize;

use super::RegistryError;

const CHAINS_JSON: &str = include_str!("../../data/chains.json");

/// A chain with an official Safe deployment.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Chain {
    /// EIP-155 chain id.
    pub chain_id: u64,
    /// Human-readable name, when `ethereum-lists/chains` has one.
    pub name: Option<String>,
    /// Symbol of the native currency (e.g. `ETH`), when known.
    pub native_symbol: Option<String>,
    /// Decimals of the native currency, when known.
    pub native_decimals: Option<u8>,
}

/// All known chains, by id.
#[derive(Debug)]
pub struct ChainTable {
    /// Upstream commit the data was generated from.
    pub source_commit: String,
    chains: BTreeMap<u64, Chain>,
}

impl ChainTable {
    /// The chain with this id, if blindsight knows it.
    pub fn get(&self, chain_id: u64) -> Option<&Chain> {
        self.chains.get(&chain_id)
    }

    /// Number of known chains.
    pub fn len(&self) -> usize {
        self.chains.len()
    }

    /// Whether the table is empty (never, for the embedded data).
    pub fn is_empty(&self) -> bool {
        self.chains.is_empty()
    }

    /// Iterates over the known chains in id order.
    pub fn iter(&self) -> impl Iterator<Item = &Chain> {
        self.chains.values()
    }
}

#[derive(Deserialize)]
struct ChainsFile {
    commit: String,
    missing_from_source: Vec<u64>,
    chains: Vec<ChainEntry>,
}

#[derive(Deserialize)]
struct ChainEntry {
    chain_id: u64,
    name: String,
    native_symbol: String,
    native_decimals: u8,
}

fn parse(json: &str) -> Result<ChainTable, RegistryError> {
    let file: ChainsFile =
        serde_json::from_str(json).map_err(|e| RegistryError::new("chains.json", e.to_string()))?;
    let mut chains = BTreeMap::new();
    for entry in file.chains {
        let chain = Chain {
            chain_id: entry.chain_id,
            name: Some(entry.name),
            native_symbol: Some(entry.native_symbol),
            native_decimals: Some(entry.native_decimals),
        };
        if chains.insert(entry.chain_id, chain).is_some() {
            return Err(RegistryError::new(
                "chains.json",
                format!("duplicate chain id {}", entry.chain_id),
            ));
        }
    }
    // Chains with a Safe deployment but no entry upstream: known, unnamed.
    for chain_id in file.missing_from_source {
        let unnamed = Chain {
            chain_id,
            name: None,
            native_symbol: None,
            native_decimals: None,
        };
        if chains.insert(chain_id, unnamed).is_some() {
            return Err(RegistryError::new(
                "chains.json",
                format!("chain id {chain_id} both named and missing"),
            ));
        }
    }
    Ok(ChainTable {
        source_commit: file.commit,
        chains,
    })
}

static CHAINS: LazyLock<Result<ChainTable, RegistryError>> = LazyLock::new(|| parse(CHAINS_JSON));

/// The embedded chain table, parsed on first use.
///
/// # Errors
///
/// Only if the embedded data is corrupt, which the tests rule out; callers
/// stop instead of continuing without the table.
pub fn chains() -> Result<&'static ChainTable, RegistryError> {
    CHAINS.as_ref().map_err(Clone::clone)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_table_is_valid() {
        let table = chains().unwrap();
        assert!(table.len() > 500);
        assert_eq!(table.source_commit.len(), 40);
        for chain in table.iter() {
            if let Some(name) = &chain.name {
                assert!(!name.is_empty() && name.chars().all(|c| c.is_ascii_graphic() || c == ' '));
            }
        }
    }

    #[test]
    fn knows_the_chains_of_the_real_vectors() {
        let table = chains().unwrap();
        for (id, name, symbol) in [
            (1, "Ethereum Mainnet", "ETH"),
            (10, "OP Mainnet", "ETH"),
            (56, "BNB Smart Chain Mainnet", "BNB"),
            (100, "Gnosis", "XDAI"),
            (137, "Polygon Mainnet", "POL"),
            (8453, "Base", "ETH"),
            (42161, "Arbitrum One", "ETH"),
            (11155111, "Ethereum Sepolia", "ETH"),
        ] {
            let chain = table.get(id).unwrap();
            assert_eq!(chain.name.as_deref(), Some(name));
            assert_eq!(chain.native_symbol.as_deref(), Some(symbol));
            assert_eq!(chain.native_decimals, Some(18));
        }
        assert!(table.get(999_999_999_999).is_none());
    }

    #[test]
    fn rejects_duplicates() {
        let json = r#"{"commit":"x","missing_from_source":[1],"chains":[
            {"chain_id":1,"name":"a","native_symbol":"A","native_decimals":18}]}"#;
        assert!(parse(json).is_err());
    }
}
